import React from 'react';
import * as THREE from 'three';
import type { Wall } from '../../core/types';
import {
  extractBuildingFootprint,
    polygonToShape,
      getEdgeInfos,
      } from '../../core/buildingFootprint3D';

      interface Props {
        walls: Wall[];
          yBottom: number;
            thickness?: number;
              slabColor?: string;
                bottomColor?: string;
                  showLight?: boolean;
                    lightColor?: string;
                      lightIntensity?: number;
                      }

                      // ✅ نمط الحجر المتناوب
                      const STONE_PROUD_WIDTH = 0.20;
                      const STONE_RECESSED_WIDTH = 0.10;
                      const STONE_PROUD_DEPTH = 0.015;
                      const STONE_RECESSED_DEPTH = 0.005;
                      const STONE_PROUD_COLOR = '#f5f0e8';
                      const STONE_RECESSED_COLOR = '#d8d0be';
                      const STONE_OVERLAP = 0.002;
                      const DEFAULT_BOTTOM_COLOR = '#F8F8F5';

                      // ✅ الإضاءة
                      const LIGHT_THICKNESS = 0.1;
                      const LIGHT_DEPTH = 0.02;
                      const LIGHT_INSET = 0.04;

                      function buildStonePattern(len: number, startProud: boolean) {
                        const stones: {
                            offsetAlong: number;
                                segLen: number;
                                    depth: number;
                                        offset: number;
                                            color: string;
                                              }[] = [];
                                                let pos = 0;
                                                  let isProud = startProud;
                                                    while (pos < len - 0.001) {
                                                        const width = isProud ? STONE_PROUD_WIDTH : STONE_RECESSED_WIDTH;
                                                            const protrude = isProud ? STONE_PROUD_DEPTH : STONE_RECESSED_DEPTH;
                                                                const remaining = len - pos;
                                                                    const actualWidth = Math.min(width, remaining);
                                                                        if (actualWidth < 0.005) break;
                                                                            const offsetAlong = -len / 2 + pos + actualWidth / 2;
                                                                                stones.push({
                                                                                      offsetAlong,
                                                                                            segLen: actualWidth,
                                                                                                  depth: protrude + STONE_OVERLAP,
                                                                                                        offset: (protrude - STONE_OVERLAP) / 2,
                                                                                                              color: isProud ? STONE_PROUD_COLOR : STONE_RECESSED_COLOR,
                                                                                                                  });
                                                                                                                      pos += actualWidth;
                                                                                                                          isProud = !isProud;
                                                                                                                            }
                                                                                                                              return { stones, endProud: isProud };
                                                                                                                              }

                                                                                                                              export const Slab3D: React.FC<Props> = ({
                                                                                                                                walls,
                                                                                                                                  yBottom,
                                                                                                                                    thickness = 0.30,
                                                                                                                                      slabColor = '#d9d4c8',
                                                                                                                                        bottomColor = DEFAULT_BOTTOM_COLOR,
                                                                                                                                          showLight = false,
                                                                                                                                            lightColor = '#FFE6A8',
                                                                                                                                              lightIntensity = 2.5,
                                                                                                                                              }) => {
                                                                                                                                                const footprint = React.useMemo(
                                                                                                                                                    () => extractBuildingFootprint(walls),
                                                                                                                                                        [walls],
                                                                                                                                                          );
                                                                                                                                                            
                                                                                                                                                              const shape = React.useMemo(
                                                                                                                                                                  () => (footprint.valid ? polygonToShape(footprint.polygon) : null),
                                                                                                                                                                      [footprint],
                                                                                                                                                                        );
                                                                                                                                                                          
                                                                                                                                                                            const edges = React.useMemo(
                                                                                                                                                                                () => (footprint.valid ? getEdgeInfos(footprint.polygon) : []),
                                                                                                                                                                                    [footprint],
                                                                                                                                                                                      );

                                                                                                                                                                                        if (!footprint.valid || !shape) return null;

                                                                                                                                                                                          const extrudeSettings = {
                                                                                                                                                                                              depth: thickness,
                                                                                                                                                                                                  bevelEnabled: false,
                                                                                                                                                                                                      curveSegments: 4,
                                                                                                                                                                                                        };
                                                                                                                                                                                                          const borderY = thickness / 2;
                                                                                                                                                                                                            const lightY = LIGHT_THICKNESS / 2;

                                                                                                                                                                                                              let globalIsProud = true;
                                                                                                                                                                                                                const allStones: { edge: any; stone: any; idx: number }[] = [];

                                                                                                                                                                                                                  edges.forEach((edge, edgeIdx) => {
                                                                                                                                                                                                                      if (edgeIdx > 0) {
                                                                                                                                                                                                                            const prev = edges[edgeIdx - 1];
                                                                                                                                                                                                                                  let angleDiff = Math.abs(edge.angle - prev.angle);
                                                                                                                                                                                                                                        if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                                                                                                                                                                                                                                              if (angleDiff > 0.1) {
                                                                                                                                                                                                                                                      globalIsProud = true;
                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                    const { stones, endProud } = buildStonePattern(edge.len, globalIsProud);
                                                                                                                                                                                                                                                                        globalIsProud = endProud;

                                                                                                                                                                                                                                                                            stones.forEach((stone, stoneIdx) => {
                                                                                                                                                                                                                                                                                  allStones.push({ edge, stone, idx: edgeIdx * 1000 + stoneIdx });
                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                              <group position={[0, yBottom, 0]}>
                                                                                                                                                                                                                                                                                                    {/* 1) جسم السقف - هذا السطر يرسم الشكل كما هو تماماً */}
                                                                                                                                                                                                                                                                                                          <mesh
                                                                                                                                                                                                                                                                                                                  rotation={[Math.PI / 2, 0, 0]}
                                                                                                                                                                                                                                                                                                                          position={[0, thickness, 0]}
                                                                                                                                                                                                                                                                                                                                  castShadow
                                                                                                                                                                                                                                                                                                                                          receiveShadow
                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                        <extrudeGeometry args={[shape, extrudeSettings]} />
                                                                                                                                                                                                                                                                                                                                                                <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                          attach="material-0"
                                                                                                                                                                                                                                                                                                                                                                                    color={slabColor}
                                                                                                                                                                                                                                                                                                                                                                                              roughness={0.85}
                                                                                                                                                                                                                                                                                                                                                                                                        metalness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                        <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                  attach="material-1"
                                                                                                                                                                                                                                                                                                                                                                                                                                            color={slabColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                      roughness={0.85}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                metalness={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </mesh>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* 2) نمط الحجر المتناوب */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {allStones.map(({ edge, stone, idx }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const offsetX = Math.cos(edge.angle) * stone.offsetAlong;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const offsetZ = -Math.sin(edge.angle) * stone.offsetAlong;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        key={`stone-${idx}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    position={[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  edge.midX + offsetX + edge.outX * stone.offset,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              edge.midZ + offsetZ + edge.outZ * stone.offset,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      rotation={[0, edge.angle, 0]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  castShadow
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <boxGeometry args={[stone.segLen, thickness, stone.depth]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color={stone.color}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                roughness={0.35}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              metalness={0.1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/* 3) شريط الإضاءة LED */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {showLight &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      edges.map((edge, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            key={`light-${i}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        position={[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      edge.midX - edge.outX * LIGHT_INSET,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lightY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  edge.midZ - edge.outZ * LIGHT_INSET,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          rotation={[0, edge.angle, 0]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <boxGeometry
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              args={[edge.len - LIGHT_INSET * 2, LIGHT_THICKNESS, LIGHT_DEPTH]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color={lightColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  emissive={lightColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                emissiveIntensity={lightIntensity}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              toneMapped={false}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };